CREATE TABLE mistri.delivery_attempt (
    destination_id text NOT NULL COLLATE pg_catalog."C",
    event_id text NOT NULL COLLATE pg_catalog."C",
    attempt integer NOT NULL,
    token text COLLATE pg_catalog."C",
    started_at bigint NOT NULL,
    deadline bigint,
    outcome text NOT NULL COLLATE pg_catalog."C",
    code text COLLATE pg_catalog."C",
    finished_at bigint,
    operator text COLLATE pg_catalog."C",
    CONSTRAINT delivery_attempt_attempt_check CHECK (((attempt >= 1) AND (attempt <= 67))),
    CONSTRAINT delivery_attempt_check CHECK ((((outcome = 'redriven'::text) AND (token IS NULL) AND (deadline IS NULL) AND (code IS NOT NULL) AND (code = 'redriven'::text) AND (finished_at IS NOT NULL) AND (finished_at = started_at) AND (operator IS NOT NULL)) OR ((outcome <> 'redriven'::text) AND (token IS NOT NULL) AND (deadline IS NOT NULL) AND (deadline > started_at) AND (operator IS NULL) AND (((outcome = 'leased'::text) AND (code IS NULL) AND (finished_at IS NULL)) OR ((outcome <> 'leased'::text) AND (code IS NOT NULL) AND (code <> 'redriven'::text) AND (finished_at IS NOT NULL) AND (finished_at >= started_at)))))),
    CONSTRAINT delivery_attempt_code_check CHECK ((code = ANY (ARRAY['accepted'::text, 'rejected'::text, 'transport'::text, 'timeout'::text, 'shutdown'::text, 'lease_expired'::text, 'redriven'::text]))),
    CONSTRAINT delivery_attempt_operator_check CHECK (((operator IS NULL) OR ((octet_length(operator) >= 1) AND (octet_length(operator) <= 128)))),
    CONSTRAINT delivery_attempt_outcome_check CHECK ((outcome = ANY (ARRAY['leased'::text, 'accepted'::text, 'rejected'::text, 'unknown'::text, 'redriven'::text]))),
    CONSTRAINT delivery_attempt_started_at_check CHECK ((started_at >= 0)),
    CONSTRAINT delivery_attempt_token_check CHECK (((token IS NULL) OR (octet_length(token) = 36)))
);
CREATE TABLE mistri.delivery_delivery (
    destination_id text NOT NULL COLLATE pg_catalog."C",
    event_id text NOT NULL COLLATE pg_catalog."C",
    receipt_id text NOT NULL COLLATE pg_catalog."C",
    ordinal integer NOT NULL,
