    redrives integer NOT NULL,
    attempt_limit integer NOT NULL,
    next_at bigint NOT NULL,
    token text COLLATE pg_catalog."C",
    lease_until bigint,
    last_code text COLLATE pg_catalog."C",
    CONSTRAINT delivery_delivery_attempt_limit_check CHECK (((attempt_limit >= 1) AND (attempt_limit <= 67))),
    CONSTRAINT delivery_delivery_attempts_check CHECK (((attempts >= 0) AND (attempts <= 67))),
    CONSTRAINT delivery_delivery_check CHECK ((attempts <= attempt_limit)),
    CONSTRAINT delivery_delivery_check1 CHECK ((((state = 'leased'::text) AND (token IS NOT NULL) AND (octet_length(token) = 36) AND (lease_until IS NOT NULL) AND (lease_until >= 0) AND (attempts > 0)) OR ((state <> 'leased'::text) AND (token IS NULL) AND (lease_until IS NULL)))),
    CONSTRAINT delivery_delivery_check2 CHECK ((((state = 'pending'::text) AND (attempts = 0) AND (last_code IS NULL)) OR ((state <> 'pending'::text) AND (attempts > 0)))),
    CONSTRAINT delivery_delivery_last_code_check CHECK ((last_code = ANY (ARRAY['accepted'::text, 'rejected'::text, 'transport'::text, 'timeout'::text, 'shutdown'::text, 'lease_expired'::text, 'redriven'::text]))),
    CONSTRAINT delivery_delivery_next_at_check CHECK ((next_at >= 0)),
    CONSTRAINT delivery_delivery_ordinal_check CHECK (((ordinal >= 0) AND (ordinal <= 31))),
    CONSTRAINT delivery_delivery_redrives_check CHECK (((redrives >= 0) AND (redrives <= 3))),
    CONSTRAINT delivery_delivery_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'leased'::text, 'retry'::text, 'unknown'::text, 'delivered'::text, 'failed'::text])))
);
